import json

class MessagePayload:
    def __init__(self, message_id: str, content: str, source: str):
        self.message_id = message_id
        self.content = content
        self.source = source

    def to_json(self):
        return json.dumps({
            "message_id": self.message_id,
            "content": self.content,
            "source": self.source
        })

import boto3
import os

class MessagingClient:
    def __init__(self):
        self.sns_client = boto3.client(
            'sns',
            region_name=os.environ.get('AWS_REGION', 'us-east-1')
        )

    def get_sns_client(self):
        return self.sns_client

import os
from messaging_client import MessagingClient
from messaging_models import MessagePayload

def publish_event(message_id: str, content: str, source: str):
    sns_client = MessagingClient().get_sns_client()
    topic_arn = os.environ.get('AWS_SNS_TOPIC_ARN')

    if not topic_arn:
        raise ValueError("AWS_SNS_TOPIC_ARN environment variable not set.")

    payload = MessagePayload(message_id, content, source)
    response = sns_client.publish(
        TopicArn=topic_arn,
        Message=payload.to_json(),
        MessageAttributes={
            'message_id': {
                'DataType': 'String',
                'StringValue': message_id
            },
            'source': {
                'DataType': 'String',
                'StringValue': source
            }
        }
    )
    return response

